    '.mq-onglets button.on{background:rgba(255,255,255,.08);color:#fff;box-shadow:inset 0 -2px 0 var(--mq,#E8A33D)}',
    '.mq-liste{flex:1;min-height:80px;overflow:auto;padding:8px 10px 12px;-webkit-overflow-scrolling:touch}',
