    const q = ps[i];
    if(!puzzleIsNative(q)) continue;
    const t = getPuzzleType(q.kind);
    if(!t || !t.enScene || !q.params || !q.params.auto || q.params.sceneId !== current.id) continue;
    if(vars[puzzleVarKey(q.id)] || sceneAbandons[q.id] === current.id) continue;
