/* ---- SaveManager : sauvegarde locale de la partie (localStorage), s\xE9par\xE9e des r\xE9glages utilisateur (bd360:settings) ---- */
const GAME_ID = (GAME.game && GAME.game.id) || GAME.title || 'game';
const SAVE_KEY = 'bd360:' + GAME_ID + (TEST_START ? ':test' : '') + ':save';
const AUTO_SAVE = HUD.autoSave !== false;
let lastSavedSig = '';
function completedPuzzleIds(){ return (GAME.puzzles||[]).filter(function(p){ return vars[puzzleVarKey(p.id)]; }).map(function(p){ return p.id; }); }
function progressSig(){ return JSON.stringify([current && current.id, inventory, vars, Array.from(discovered).sort(), dlgState && dlgState.nodeId]); }
function markSaved(){ lastSavedSig = progressSig(); }
function buildSave(){
  return {
    v:4, gameId: GAME_ID, currentSceneId: current && current.id, inventory: inventory,
    discovered: Array.from(discovered), variables: vars, completedPuzzles: completedPuzzleIds(),
    dialogue: dialogSaveState(dlgState), dialogSeen: dlgSeen,
    puzzleState: puzzleStates, timestamp: Date.now(),
  };
}
