/*  Les ambiances de la sc\xE8ne : des boucles superposables, qui se
    croisent d'une sc\xE8ne \xE0 l'autre. Celle qui est pr\xE9sente des deux
    c\xF4t\xE9s continue sans repartir du d\xE9but. */
function syncAmbience(){
  const st = HomeSettings.get();
  const scene = playerScreen !== 'home' ? current : null;
  const liste = scene ? audioSceneAmbience(aGameAudio, scene) : [];
  const fondu = aGameAudio && aGameAudio.fade ? aGameAudio.fade.ambience : 1.2;
  aAmbience(liste, fondu, !(!st.music || st.mute));
}

/* ------------------------------------------------------------------ */
/*  Normalisation des actions et des conditions                       */
/*  Deplace ici pour etre disponible aussi dans le player : les       */
/*  dialogues en ont besoin au moment ou ils sont ouverts.            */
/* ------------------------------------------------------------------ */
/*  Lot 1 : une direction de regard, une transition, et la liste \xE0 plat
    des actions (celles rang\xE9es dans \xAB si \xBB et \xAB au hasard \xBB comprises). */
function normRegard(r) {
  if (!r || typeof r !== "object") return undefined;
  const y = parseFloat(r.yaw), p = parseFloat(r.pitch);
  return isFinite(y) ? { yaw: y, pitch: isFinite(p) ? Math.max(-1.55, Math.min(1.55, p)) : 0 } : undefined;
}
