      if (type === "fadeDown") return [{ opacity: 0, transform: "translateY(-40px)" }, { opacity: 1, transform: "translateY(0)" }];
      if (type === "fadeLeft") return [{ opacity: 0, transform: "translateX(-40px)" }, { opacity: 1, transform: "translateX(0)" }];
      if (type === "fadeRight") return [{ opacity: 0, transform: "translateX(40px)" }, { opacity: 1, transform: "translateX(0)" }];
