      applyTransform(T);
      const fs = (L.fontSize / (c.reference.width || 1920)) * unit * (settings.textScale || 1);
      if (T.text) { T.text.style.fontSize = fs + "px"; T.text.style.letterSpacing = (L.letterSpacing / (c.reference.width || 1920)) * unit + "px"; }
      if (T.btn) { T.btn.style.fontSize = fs + "px"; T.btn.style.letterSpacing = (L.letterSpacing / (c.reference.width || 1920)) * unit + "px"; }
